import clsx from 'clsx';
import React, {
  HTMLAttributes,
  KeyboardEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';

import { _useInternalTimeframeSelectorContext } from './hooks/useInternalTimeframeSelectorContext.js';
import { useItemFormatting } from './hooks/useItemFormatting.js';
import { useTimeframeSelectorContext } from './hooks/useTimeframeSelectorContext.js';
import type { PresetItemVariants } from './TimeframeSelectorPresets.sty.js';
import {
  timeframeSelectorPresetItemCSS,
  timeframeSelectorPresetItemContainerCSS,
  timeframeSelectorPresetItemMediaQuery,
  timeframeSelectorPresetItemNameCSS,
  timeframeSelectorPresetItemValueCSS,
  tooltipPresetItemColor,
  tooltipPresetItemWrapper,
} from './TimeframeSelectorPresets.sty.js';
import { _isOutsideRange } from './utils/timeframe-selection.js';
import { _useId } from '../../core/hooks/useId.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Grid } from '../../layouts-core/grid/Grid.js';
import { Tooltip } from '../../overlays/tooltip/Tooltip.js';
import { Text } from '../../typography/Text.js';
import { _parseValue } from '../forms-core/time/timeParser.js';

//#region Typings
export interface TimeframeSelectorPresetItemProps
  extends HTMLAttributes<HTMLLIElement>,
    DataTestId,
    StylingProps,
    WithChildren {
  /** The value of the timeframe preset. */
  value: {
    /** Start of the time frame. */
    from: string;
    /** End of the time frame. */
    to: string;
  };
}
//#endregion

/** TimeframeSelector preset item shown inside the presets list of the overlay. */
export const PresetItem = (
  props: TimeframeSelectorPresetItemProps & { _isSelected?: boolean },
) => {
  const {
    children,
    value,
    _isSelected: isSelected = false,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: TimeframeSelectorPresetItemProps & { _isSelected?: boolean } = props;

  const [openTooltip, setOpenTooltip] = useState(false);

  const { onChange } = useTimeframeSelectorContext();
  const { min, max, precision } = _useInternalTimeframeSelectorContext();

  const isDisabled = _isOutsideRange(value, min, max);

  const tooltipId = _useId();
  const tooltipFocusProps = {
    onFocus: useCallback(
      () => !isDisabled && setOpenTooltip(true),
      [isDisabled],
    ),
    onBlur: useCallback(() => setOpenTooltip(false), []),
  };

  const { focusProps, focusClassName } = useFocusRing({
    variant: isSelected && !isDisabled ? 'primary' : 'neutral',
    disabled: isDisabled,
  });

  let state: NonNullable<PresetItemVariants>['state'] = isSelected
    ? 'selected'
    : 'rest';
  if (isDisabled) {
    state = 'disabled';
  }

  const {
    timeframeDisplayValue,
    formattedPresetItemValue,
    tooltipFormattedTimeValueStart,
    tooltipFormattedTimeValueEnd,
    isAbsoluteTimeframe,
    isInvalid,
  } = useItemFormatting(value, children, precision);

  /** Handle clicking on the timeframe selector preset item */
  const handleItemClick = useCallback(() => {
    if (isDisabled) {
      return;
    }

    const { from, to } = _parseValue(value);

    if (from && to) {
      onChange({
        from,
        to,
      });
    }
  }, [isDisabled, value, onChange]);

  /**
   * Temporary keydown listener to provide the possibility to select items via keyboard
   * Will change as soon as we switch to the reusable listbox component.
   */
  const handleItemKeyDown = useCallback(
    (event: KeyboardEvent<HTMLLIElement>) => {
      if (isDisabled) {
        return;
      }

      if (
        event.code === 'Enter' ||
        event.code === 'NumpadEnter' ||
        event.code === 'Space'
      ) {
        handleItemClick();
      }
    },
    [handleItemClick, isDisabled],
  );

  const liRef = useRef<HTMLLIElement | null>(null);

  useEffect(() => {
    if (isSelected) {
      liRef.current?.scrollIntoView();
    }
    // we don't want to scroll the element into view when isSelected changes, but only on the first render
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return isInvalid ? null : (
    <li
      ref={liRef}
      role="option"
      aria-selected={isSelected}
      aria-disabled={isDisabled}
      className={clsx([
        focusClassName,
        timeframeSelectorPresetItemCSS({
          state,
        }),
        consumerClassName,
      ])}
      onClick={handleItemClick}
      onKeyDown={handleItemKeyDown}
      data-testid={dataTestId}
      style={consumerStyle}
      {...mergeProps(remainingProps, focusProps, tooltipFocusProps)}
    >
      <Tooltip
        id={tooltipId}
        text={
          <Flex flexDirection="column" className={tooltipPresetItemColor}>
            <Flex gap={0} flexDirection="column">
              <Text textStyle="base-emphasized">{timeframeDisplayValue}</Text>
              <Text textStyle="small">{formattedPresetItemValue}</Text>
            </Flex>
            {!isAbsoluteTimeframe && (
              <Flex gap={0} flexDirection="column">
                <Text textStyle="small">{tooltipFormattedTimeValueStart}</Text>
                <Text textStyle="small">{tooltipFormattedTimeValueEnd}</Text>
              </Flex>
            )}
          </Flex>
        }
        placement="right"
        fallbackPlacements={[
          'right-end',
          'bottom-end',
          'bottom',
          'bottom-start',
          'left-end',
          'left',
          'left-start',
        ]}
        open={openTooltip}
        onOpenChange={setOpenTooltip}
        disabled={isDisabled}
      >
        <div
          className={tooltipPresetItemWrapper({ isSelected, isDisabled })}
          aria-describedby={tooltipId}
        >
          <Grid className={timeframeSelectorPresetItemContainerCSS}>
            <Text
              as={Flex}
              className={timeframeSelectorPresetItemNameCSS}
              textStyle="base-emphasized"
            >
              {timeframeDisplayValue}
            </Text>
            <Text
              as={Flex}
              textStyle="small"
              className={clsx(
                timeframeSelectorPresetItemMediaQuery,
                timeframeSelectorPresetItemValueCSS({
                  state,
                }),
              )}
            >
              {formattedPresetItemValue}
            </Text>
          </Grid>
        </div>
      </Tooltip>
    </li>
  );
};

PresetItem['displayName'] = 'TimeframeSelector.PresetItem';
